const $=s=>document.querySelector(s);
const money=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(n)||0);
const currentPrice=p=>Number.isFinite(Number(p.salePrice))&&Number(p.salePrice)>0&&Number(p.salePrice)<Number(p.price)?Number(p.salePrice):Number(p.price)||0;
const paymentBrands=[['Apple Pay','apple-pay'],['Bancontact','bancontact'],['Google Pay','google-pay'],['iDEAL','ideal'],['Klarna','klarna'],['Mastercard','mastercard'],['Maestro','maestro'],['PayPal','paypal'],['Visa','visa'],['American Express','american-express']];
const paymentMarks=()=>paymentBrands.map(([name,file])=>`<span class="payment-mark" title="${name}"><img src="/payments/${file}.svg" alt="${name}"></span>`).join('');
const linkIcon=()=>'<svg class="link-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M10 13a5 5 0 0 0 7.07 0l3-3a5 5 0 0 0-7.07-7.07l-1.71 1.71M14 11a5 5 0 0 0-7.07 0l-3 3a5 5 0 0 0 7.07 7.07l1.71-1.71"/></svg>'; 
function updateAccountHeader(signedIn=headerSignedIn){headerSignedIn=signedIn;const status=$('#account-status'),label=$('#account-status-label'),link=document.querySelector('.account-link');if(!status||!label||!link)return;status.classList.toggle('is-signed-in',signedIn);label.textContent=signedIn?'Signed in':'Guest';link.setAttribute('aria-label',signedIn?'Account, signed in':'Account, guest')}
async function syncAccountHeader(){try{const data=await api('/api/account/me');updateAccountHeader(data.authenticated)}catch{updateAccountHeader(false)}}
let catalog=[];let accountState=null;let headerSignedIn=false;let accountSection='overview';let adminCatalog=[];let toastTimer;let spotlightTimers=[];let bagStatusMessage='';let bagDrawerCloseTimer;
const bag=()=>JSON.parse(localStorage.getItem('gr-bag')||'[]');
function saveBag(lines){localStorage.setItem('gr-bag',JSON.stringify(lines));updateBag()}
function updateBag(){$('#bag-count').textContent=bag().reduce((n,x)=>n+x.quantity,0);renderBagDrawer()}
function renderBagDrawer(){const root=$('#bag-drawer');if(!root)return;const lines=bag(),count=lines.reduce((n,x)=>n+x.quantity,0),subtotal=lines.reduce((n,x)=>{const p=catalog.find(y=>y.id===x.id);return n+(p?currentPrice(p)*x.quantity:0)},0);$('#bag-drawer-count').textContent=`(${count})`;$('#bag-drawer-status').textContent=bagStatusMessage;$('#bag-drawer-content').innerHTML=lines.length?lines.map(line=>{const p=catalog.find(x=>x.id===line.id);if(!p)return '';return `<article class="bag-drawer-item"><img src="${esc(p.image||'')}" alt="${esc(p.name)}" loading="lazy"><div class="bag-drawer-item-copy"><strong>${esc(p.name)}</strong><span>${money(currentPrice(p))}</span><div class="bag-drawer-quantity"><button type="button" data-bag-action="decrease" data-id="${esc(p.id)}" aria-label="Decrease quantity of ${esc(p.name)}">&#8722;</button><span aria-label="Quantity">${line.quantity}</span><button type="button" data-bag-action="increase" data-id="${esc(p.id)}" aria-label="Increase quantity of ${esc(p.name)}">+</button></div></div><div class="bag-drawer-item-end"><strong>${money(currentPrice(p)*line.quantity)}</strong><button type="button" class="bag-drawer-remove" data-bag-action="remove" data-id="${esc(p.id)}" aria-label="Remove ${esc(p.name)} from bag">Remove</button></div></article>`}).join(''):`<div class="bag-drawer-empty"><span aria-hidden="true">&#176;</span><h3>Your bag is empty.</h3><p>There is room for something lovely.</p><button type="button" class="button button-outline" data-bag-go="/collections">Explore the collection</button></div>`;$('#bag-drawer-footer').hidden=!lines.length;$('#bag-drawer-footer').innerHTML=lines.length?`<div class="bag-drawer-subtotal"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><p>Shipping and applicable taxes are calculated after setup.</p><button type="button" class="button button-dark bag-drawer-checkout" data-bag-go="/checkout">Continue to checkout <span>${linkIcon()}</span></button><button type="button" class="bag-drawer-view" data-bag-go="/cart">View full bag</button>`:''}
function openBagDrawer(message=''){clearTimeout(bagDrawerCloseTimer);bagStatusMessage=message;renderBagDrawer();const dialog=$('#bag-drawer');dialog.classList.remove('is-closing');dialog.inert=false;if(!dialog.open){dialog.dataset.restoreFocus='true';dialog.showModal()}$('#bag-trigger').setAttribute('aria-expanded','true');$('#bag-drawer-close')?.focus()}
function closeBagDrawer(restoreFocus=true){const dialog=$('#bag-drawer');if(!dialog.open){if(restoreFocus)$('#bag-trigger').focus();return}dialog.dataset.restoreFocus=String(restoreFocus);if(dialog.classList.contains('is-closing'))return;if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){dialog.close();return}dialog.inert=true;dialog.classList.add('is-closing');bagDrawerCloseTimer=setTimeout(()=>{if(dialog.open)dialog.close()},240)}
function showToast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600)}
async function api(url,options={}){const r=await fetch(url,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await r.json().catch(()=>({}));if(!r.ok)throw Error(data.error||'Something went wrong.');return data}
const art=(p,large=false)=>{
 if(p.image)return `<img class="product-art product-photo ${large?'art-large':''}" src="${esc(p.image)}" alt="${esc(p.name)}" loading="lazy">`;
 const c=p.color||'#c7955f';let shape='';
 if(p.shape==='echo')shape=`<path d="M205 87c-48-43-103-10-88 35 11 33 71 42 82 77 12 36-23 61-64 45-18-7-30-23-36-38" fill="none" stroke="#76543d" stroke-width="10" stroke-linecap="round"/><circle cx="205" cy="87" r="16" fill="${c}"/><circle cx="99" cy="206" r="16" fill="${c}"/>`;
 else if(p.shape==='blocks')shape=`<path d="M57 202V119a22 22 0 0 1 22-22h35v105z" fill="${c}"/><path d="M114 202v-61a22 22 0 0 1 22-22h45v83z" fill="#d5aa7b"/><path d="M181 202v-82h41a22 22 0 0 1 22 22v60z" fill="#af7753"/>`;
 else if(p.shape==='spinner')shape=`<circle cx="150" cy="150" r="66" fill="${c}"/><circle cx="150" cy="150" r="42" fill="#e0c49f"/><circle cx="150" cy="150" r="15" fill="#795943"/><path d="M150 33v55M150 212v55M33 150h55M212 150h55" stroke="#835d41" stroke-width="8" stroke-linecap="round"/>`;
 else if(p.shape==='rattle')shape=`<circle cx="150" cy="105" r="45" fill="${c}"/><path d="M137 139h26v89a13 13 0 0 1-26 0z" fill="#a97952"/><path d="M135 103c8-20 22-20 30 0" fill="none" stroke="#805b40" stroke-width="6" stroke-linecap="round"/>`;
 else if(p.shape==='column')shape=`<path d="M113 57h74l-10 39 19 22v110H96V118l19-22z" fill="${c}"/><path d="M113 57h74l-10 39h-54z" fill="#dfc29a"/><ellipse cx="149" cy="120" rx="53" ry="15" fill="#bc8e68"/>`;
 else shape=`<circle cx="149" cy="150" r="68" fill="${c}"/><circle cx="149" cy="150" r="40" fill="#e0bd91"/><circle cx="149" cy="150" r="14" fill="#866248"/><path d="M149 48v28M149 224v28M47 150h28M223 150h28" stroke="#926846" stroke-width="7" stroke-linecap="round"/>`;
 return `<svg class="product-art ${large?'art-large':''}" viewBox="0 0 300 300" role="img" aria-label="Illustration of ${esc(p.name)}"><defs><radialGradient id="glow"><stop stop-color="#fff" stop-opacity=".62"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient></defs><circle cx="150" cy="146" r="112" fill="url(#glow)"/>${shape}<ellipse cx="150" cy="250" rx="76" ry="9" fill="#6d503d" opacity=".1"/></svg>`
};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function card(p,i=0){const sale=currentPrice(p)<Number(p.price),second=p.images?.[1];return `<article class="product-card ${sale?'on-sale':''}" style="--delay:${i*60}ms"><a class="product-image ${i%3===1?'image-tall':''}" href="/products/${encodeURIComponent(p.id)}">${art(p)}${second?`<img class="hover-photo" src="${esc(second)}" alt="" loading="lazy">`:''}${sale?'<span class="sale-badge">Sale</span>':''}${p.stock<=0?'<span class="product-badge is-sold-out">Sold out</span>':''}</a><div class="product-meta"><div><a class="product-name" href="/products/${encodeURIComponent(p.id)}">${esc(p.name)}</a><span class="product-category">${esc(p.category)}</span></div><span class="product-price ${sale?'sale-price':''}">${sale?`<s>${money(p.price)}</s> `:''}${money(currentPrice(p))}</span></div></article>`}
function flashCard(p,i,animated=false){const sale=currentPrice(p)<Number(p.price);const stockLabel=sale?'Sale':'Sold out';return `<article class="flash-card ${sale?'on-sale':''} ${animated?'':'flash-card-static'}" ${animated?`data-flash-card data-index="${i}" aria-hidden="${i!==0}"`:''}><a href="/products/${encodeURIComponent(p.id)}" class="flash-card-link"><div class="flash-card-image">${art(p,true)}${p.images?.[1]?`<img class="flash-hover-photo" src="${esc(p.images[1])}" alt="" loading="lazy">`:''}<span class="flash-card-mark">GR / ${String(i+1).padStart(2,'0')}</span>${sale||p.stock<=0?`<span class="flash-card-status ${sale?'is-sale':'is-sold-out'}">${stockLabel}</span>`:''}</div><div class="flash-card-info"><div><span class="eyebrow">${esc(p.category)} / ${esc(p.collection)}</span><h3>${esc(p.name)}</h3></div><span class="flash-card-price">${sale?`<s>${money(p.price)}</s> `:''}${money(currentPrice(p))}${linkIcon()}</span></div></a><button class="flash-card-add" type="button" data-add="${esc(p.id)}" ${p.stock>0?'':'disabled'}>${p.stock>0?'Add to bag':'Sold out'}</button></article>`}
function flashCards(items,id='product-carousel'){if(!items.length)return '';return `<section class="product-flash-section" id="${esc(id)}" data-flash-carousel aria-label="Studio picks"><div class="flash-heading"><span class="eyebrow">A CLOSER LOOK / THE STUDIO PICKS</span><h2>Small things,<br><em>big feeling.</em></h2><p>One at a time, take a closer look. Thoughtful forms, playful details, and little objects ready to find their place.</p><a class="arrow-link" href="/collections">All objects <span>${linkIcon()}</span></a><div class="flash-controls"><button type="button" data-flash-prev aria-label="Previous product">&#8592;</button><span data-flash-count>01 / ${String(items.length).padStart(2,'0')}</span><button type="button" data-flash-next aria-label="Next product">&#8594;</button></div></div><div class="flash-stage" data-flash-stage>${items.map((p,i)=>flashCard(p,i,true)).join('')}</div></section>`}
function setupFlashCards(){spotlightTimers.forEach(clearInterval);spotlightTimers=[];document.querySelectorAll('[data-flash-carousel]').forEach(root=>{const cards=[...root.querySelectorAll('[data-flash-card]')],count=root.querySelector('[data-flash-count]');if(!cards.length||!count)return;let active=0,timer=null;const show=index=>{active=(index+cards.length)%cards.length;cards.forEach((card,i)=>{const depth=(i-active+cards.length)%cards.length;card.dataset.layer=depth<3?String(depth):(i>active?'away-left':'away-right');card.setAttribute('aria-hidden',String(depth!==0));card.inert=depth!==0});count.textContent=`${String(active+1).padStart(2,'0')} / ${String(cards.length).padStart(2,'0')}`};const stop=()=>{if(timer){clearInterval(timer);spotlightTimers=spotlightTimers.filter(x=>x!==timer);timer=null}};const play=()=>{stop();if(cards.length>1&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){timer=setInterval(()=>show(active+1),2500);spotlightTimers.push(timer)}};root.querySelector('[data-flash-next]')?.addEventListener('click',()=>show(active+1));root.querySelector('[data-flash-prev]')?.addEventListener('click',()=>show(active-1));root.addEventListener('pointerenter',stop);root.addEventListener('pointerleave',play);root.addEventListener('focusin',stop);root.addEventListener('focusout',e=>{if(!root.contains(e.relatedTarget))play()});show(0);play()})}
function grid(items){return `<div class="static-flash-grid">${items.map((p,i)=>flashCard(p,i,false)).join('')}</div>`}
function salePromo(){return `<section class="sale-feature"><div><span class="eyebrow">A LITTLE LESS / THE SALE EDIT</span><h2>Good things,<br><em>for a little less.</em></h2><p>Selected pieces at considered prices.</p></div><a class="button button-outline" href="/sale">Explore the sale ${linkIcon()}</a><span class="sale-spark">%</span></section>`}
function illustratedIntro(eyebrow,title,description,image,extra=''){return `<section class="page-intro illustrated-intro ${extra}"><div class="page-intro-layout"><div class="page-intro-copy"><span class="eyebrow">${eyebrow}</span><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div><div class="page-intro-art"><img src="/source/page-illustrations/${image}.svg" alt="" decoding="async"></div></div></section>`}
function salePage(){const items=catalog.filter(p=>currentPrice(p)<Number(p.price));return `<section class="page-intro sale-intro"><span class="eyebrow">A LITTLE LESS / THE SALE EDIT</span><h1>Good things,<br><em>for a little less.</em></h1><p>Selected pieces at considered prices.</p></section>${items.length?`<section class="section sale-grid-section">${grid(items)}</section>`:`<section class="sale-empty"><span class="sale-spark">%</span><h2>A little pause<br>between offers.</h2><p>There are no sale prices at the moment. This page will show offers when the studio adds them.</p><a class="arrow-link" href="/collections">Browse the collection ${linkIcon()}</a></section>`}`}
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow">GR STUDIO / SMALL OBJECTS</span><h1>GR <em>Studio.</em></h1><p>Thoughtful wooden objects for play, sound, and everyday living.</p><a class="button button-dark" href="/collections">Explore the collection ${linkIcon()}</a></div><div class="hero-visual"><div class="hero-art-orbit"><img class="hero-object-vector" src="/source/hero-products.svg?v=${Date.now()}" alt="Straight-on vector illustration of a wooden miniature violin and bowling set." decoding="async"></div><div class="hero-caption"><span>01 / A STUDY IN MOTION</span><span>FORM STUDIES — 2026</span></div><span class="hero-side-note">OBJECTS TO KEEP CLOSE</span></div><div class="hero-stamp">GR<br><span>°</span></div></section>${flashCards(catalog.filter(p=>p.status==='published').slice(0,5))}${salePromo()}<section class="collection-band"><div class="collection-copy"><span class="eyebrow">A WORLD IN MINIATURE</span><h2>Find your<br><em>kind of curious.</em></h2><p>For little hands, long afternoons, and shelves that could use a story.</p><a class="button button-outline" href="/collections">Explore collections ${linkIcon()}</a></div><div class="collection-tiles"><a href="/collections/toys" class="collection-tile tile-toys"><span>01 / PLAY</span>${art(catalog.find(p=>p.category==='Toys')||catalog[0])}<strong>Play forms ${linkIcon()}</strong></a><a href="/collections/objects" class="collection-tile tile-objects"><span>02 / LIVING</span>${art(catalog.find(p=>p.category==='Objects')||catalog[0])}<strong>Objects ${linkIcon()}</strong></a><a href="/collections/instruments" class="collection-tile tile-sound"><span>03 / SOUND</span>${art(catalog.find(p=>p.category==='Instruments')||catalog[0])}<strong>Sound objects ${linkIcon()}</strong></a></div></section><section class="manifesto"><span class="eyebrow">A NOTE FROM THE STUDIO</span><p>We believe a small thing can hold a <em>whole world.</em><br>That a curve can become a path, and a quiet shape can start a story.</p><a class="arrow-link" href="/about">A little more about us ${linkIcon()}</a><div class="manifesto-scribble">g<span>r</span></div></section><section class="material-section"><div class="material-art"><div class="material-ring"></div><div class="material-label label-one">FORM<br><span>01</span></div><div class="material-label label-two">FEEL<br><span>02</span></div><div class="material-object">${art(catalog.find(p=>p.id==='little-echo')||catalog[0],true)}</div></div><div class="material-copy"><span class="eyebrow">DETAIL / OBJECT / INTENTION</span><h2>Thought in<br>every <em>curve.</em></h2><p>Clear lines, softened edges, and a little space for a story to begin. Every detail starts with curiosity.</p><a class="arrow-link" href="/about">The way we think ${linkIcon()}</a></div></section><section class="newsletter-section"><span class="eyebrow">POSTCARDS FROM THE STUDIO</span><h2>Curiosity, <em>occasionally.</em></h2><p>New objects and small notes from the studio. Never too much.</p><form class="newsletter-large" id="newsletter-form-home"><label class="sr-only" for="home-email">Email address</label><input type="email" id="home-email" name="email" placeholder="Your email address" autocomplete="email" required><label class="newsletter-consent"><input type="checkbox" name="consent" required><span>I agree to receive occasional emails from GR Studio.</span></label><button aria-label="Subscribe">Sign me up ${linkIcon()}</button><p class="newsletter-message" id="home-newsletter-message" aria-live="polite"></p></form></section>`}
function shop(){const cats=['All',...new Set(catalog.map(p=>p.category))];return `<section class="page-intro"><h1>Collection</h1></section><section class="section shop-section"><div class="shop-toolbar"><div class="filter-pills" id="filter-pills">${cats.map((c,i)=>`<button class="filter-pill ${i===0?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="shop-controls"><span id="result-count">${catalog.length} pieces</span><select id="sort" aria-label="Sort products"><option value="featured">Sort: featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="az">Name: A to Z</option></select></div></div><div id="shop-grid">${grid(catalog)}</div></section><p class="catalog-disclaimer">Explore playful wooden objects, small instruments, and thoughtful forms for everyday spaces. Contact GR Studio if you would like more detail about a piece.</p>`}
function gallery(p){const images=p.images?.length?p.images:[p.image].filter(Boolean);if(!images.length)return art(p,true);return `<div class="gallery-main"><img id="gallery-main-image" class="product-art product-photo art-large" src="${esc(images[0])}" alt="${esc(p.name)}" fetchpriority="high"></div>${images.length>1?`<div class="gallery-thumbs" aria-label="More product views">${images.map((src,i)=>`<button class="gallery-thumb ${i===0?'selected':''}" type="button" data-gallery-src="${esc(src)}" aria-label="View ${esc(p.name)}, image ${i+1}"><img src="${esc(src)}" alt="" loading="lazy"></button>`).join('')}</div>`:''}`}
function detail(id){const p=catalog.find(x=>x.id===id);if(!p)return `<section class="empty-state"><h1>That object wandered off.</h1><a class="button button-dark" href="/collections">Back to the collection</a></section>`;const related=catalog.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,3);return `<div class="breadcrumbs"><a href="/">Home</a><span>/</span><a href="/collections">Collections</a><span>/</span>${esc(p.name)}</div><section class="product-detail"><div class="detail-product-card"><div class="detail-visual ${p.image?'has-gallery':''}">${gallery(p)}${currentPrice(p)<Number(p.price)?'<span class="detail-sale-badge">SALE</span>':''}${p.stock<=0?'<span class="detail-sold-out-badge">SOLD OUT</span>':''}<span class="image-note">GR STUDIO / ${esc(p.sku||'GR')}</span></div><div class="detail-card-info"><div><span class="eyebrow">${esc(p.category)} / ${esc(p.collection)}</span><h1>${esc(p.name)}</h1></div><div class="detail-price ${currentPrice(p)<Number(p.price)?'sale-price':''}">${currentPrice(p)<Number(p.price)?`<s>${money(p.price)}</s> `:""}${money(currentPrice(p))} <small>EUR &middot; current price</small></div></div></div><div class="detail-copy"><p>${esc(p.description)}</p><div class="detail-spec"><div><span>Size</span><b>${esc(p.dimensions||'A compact form')}</b></div><div><span>Materials</span><b>${esc(p.materials||'Wood and complementary materials')}</b></div><div><span>Availability</span><b>${p.stock>0?'In stock &middot; '+p.stock:'Currently unavailable'}</b></div></div><div class="detail-alert">Browse the images for a closer look. For more detail about a piece, contact the studio.</div><div class="add-row"><label for="quantity">Qty</label><input type="number" id="quantity" value="1" min="1" max="${Math.max(1,p.stock)}" ${p.stock<1?'disabled':''}><button class="button button-dark" data-add="${esc(p.id)}" ${p.stock<1?'disabled':''}>${p.stock>0?'Add to bag':'Sold out'} <span>${linkIcon()}</span></button></div><details><summary>Shipping & returns</summary><p>We ship worldwide, with free shipping on orders over $50. For return help, contact the studio before sending an item back.</p></details><details><summary>Care</summary><p>For wooden surfaces, wipe gently with a soft, dry cloth and avoid prolonged moisture.</p></details></div></section>${related.length?`<section class="section related-section"><div class="section-heading"><div><span class="eyebrow">STAY A LITTLE LONGER</span><h2>More to <em>meet.</em></h2></div></div>${grid(related)}</section>`:''}`}
function cartPage(){const lines=bag();const list=lines.map(line=>{const p=catalog.find(x=>x.id===line.id);if(!p)return '';return `<div class="cart-line"><div class="cart-thumb">${art(p)}</div><div class="cart-item-copy"><a href="/products/${encodeURIComponent(p.id)}">${esc(p.name)}</a><span>${esc(p.category)}</span><strong>${money(currentPrice(p))}</strong></div><label class="quantity-wrap">Qty<input type="number" min="1" max="${p.stock||1}" value="${line.quantity}" data-qty="${esc(p.id)}"></label><strong class="line-total">${money(currentPrice(p)*line.quantity)}</strong><button class="remove-line" data-remove="${esc(p.id)}" aria-label="Remove ${esc(p.name)}">×</button></div>`}).join('');const subtotal=lines.reduce((n,x)=>n+currentPrice(catalog.find(p=>p.id===x.id)||{})*x.quantity,0);return `<section class="page-intro cart-intro"><span class="eyebrow">A THOUGHTFUL LITTLE COLLECTION</span><h1>Your <em>bag.</em></h1></section><section class="cart-layout"><div class="cart-lines">${list||`<div class="empty-bag"><span>°</span><h2>A little space<br>for something lovely.</h2><p>Your bag is waiting for its first object.</p><a class="button button-dark" href="/collections">Explore the collection ${linkIcon()}</a></div>`}</div>${lines.length?`<aside class="order-summary"><span class="eyebrow">THE SUMMARY</span><div class="summary-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="summary-row"><span>Shipping</span><span>${subtotal>50?'Free':'Confirmed with your order'}</span></div><div class="summary-row summary-total"><span>Estimated total</span><strong>${money(subtotal)}</strong></div><p>Shipping is free on orders over $50. Any other delivery charges are confirmed before payment.</p><a class="button button-dark full-button" href="/checkout">Continue to checkout ${linkIcon()}</a><a class="continue-link" href="/collections">Continue exploring</a></aside>`:''}</section>`}
function checkout(){const lines=bag(),subtotal=lines.reduce((n,x)=>n+currentPrice(catalog.find(p=>p.id===x.id)||{})*x.quantity,0);if(!lines.length)return `${illustratedIntro('ONE LAST LITTLE STEP','Make it <em>yours.</em>','','shopping-bags_nfsf','checkout-intro')}<section class="empty-state"><h1>Your bag is still empty.</h1><a class="button button-dark" href="/collections">Explore the collection</a></section>`;return `${illustratedIntro('ONE LAST LITTLE STEP','Make it <em>yours.</em>','Online payment is not available yet. Your order request is saved without taking payment.','online-shopping_po8w','checkout-intro')}<form id="checkout-form" class="checkout-layout"><div class="checkout-fields"><section class="checkout-card"><span class="eyebrow">01 / CONTACT</span><h2>Where to reach you</h2><label>Email address<input type="email" name="email" autocomplete="email" required></label><label>Full name<input name="name" autocomplete="name" required></label></section><section class="checkout-card"><span class="eyebrow">02 / DELIVERY</span><h2>Where it should go</h2><div id="saved-address-picker" hidden></div><label>Address<input name="line1" autocomplete="address-line1" required></label><label>Apartment, suite, etc. <small>Optional</small><input name="line2" autocomplete="address-line2"></label><div class="form-split"><label>City<input name="city" autocomplete="address-level2" required></label><label>Region<input name="region" autocomplete="address-level1"></label></div><div class="form-split"><label>Postal code<input name="postalCode" autocomplete="postal-code" required></label><label>Country<select name="country" autocomplete="country-name" required><option value="">Choose a country</option>${['Italy','France','Germany','Spain','Netherlands','United Kingdom','United States','Canada','Other'].map(c=>`<option>${c}</option>`).join('')}</select></label></div><div class="demo-notice">We ship worldwide, with free shipping on orders over $50. Your order request is saved without payment.</div></section><section class="checkout-card"><span class="eyebrow">03 / PAYMENT</span><h2>A note about payment</h2><p>Online card payment is not available yet. No card details are collected on this site.</p><div class="payment-list future-payment" aria-label="Payment options">${paymentMarks()}</div></section></div><aside class="order-summary checkout-summary"><span class="eyebrow">YOUR OBJECTS</span>${lines.map(l=>{const p=catalog.find(x=>x.id===l.id);return p?`<div class="checkout-line"><span class="checkout-line-product"><img src="${esc(p.image||p.images?.[0]||'')}" alt=""><span>${esc(p.name)}<small>× ${l.quantity}</small></span></span><strong>${money(currentPrice(p)*l.quantity)}</strong></div>`:''}).join('')}<div class="summary-row"><span>Subtotal</span><strong>${money(subtotal)}</strong></div><div class="summary-row"><span>Shipping</span><span>${subtotal>50?'Free':'Confirmed with your order'}</span></div><div class="summary-row summary-total"><span>Estimated total</span><strong>${money(subtotal)}</strong></div><button class="button button-dark full-button" type="submit">Submit order request ${linkIcon()}</button><p>No payment is taken when you submit this request.</p><div class="legal-check">By submitting your request, you agree to the GR Studio terms and privacy policy.</div></aside></form>`}
const pages={about:['Objects with room for a story.','GR Studio brings together playful wooden objects, small instruments, and thoughtful details for everyday spaces.','We are drawn to simple forms that invite a hand, a question, or a new use. Each piece leaves a little room for imagination, whether it is picked up, played with, or kept close.'],contact:['A note finds its way.','Have a question about a piece, an order, or a delivery? We would be glad to help.','Send a note to the studio and include your order reference when you have one. A little detail about what you need will help us get back to you with the right information.'],faq:['A few useful answers.','A little more about the objects, ordering, delivery, and getting in touch with GR Studio.','What are the pieces made from? The collection focuses on wood. Materials for each piece are listed on its product page.\nWhere do you ship? We ship worldwide, with free shipping on orders over $50.\nHow do returns work? Contact the studio before sending an item back so we can guide you through the next steps.\nCan I pay online? Online card payments are not available yet. Orders submitted here remain unpaid until payment is arranged.'],shipping:['The journey from here to there.','We ship worldwide, with free shipping on orders over $50.','Delivery times and options depend on your destination. For a delivery estimate or help with an international order, get in touch with the studio before placing your order. Any applicable duties or import charges are determined by the destination.'],returns:['A clear way back.','If something is not right with your order, we will help you understand the next steps.','Please contact the studio before sending an item back. We will confirm the options for your order and guide you through the return process.'],privacy:['Your details stay yours.','This site uses local browser storage to remember the items in your bag and your cookie preferences. If you submit an order, the contact, delivery, and item details you provide are saved with that order.','If you create an account, your name and email are stored with a protected password hash so you can sign in and view orders placed while signed in. Order contact and delivery details are stored with each order. If you subscribe to studio emails, your address and opt-in time are stored so the subscription can be managed. Contact GR Studio to ask about your account or subscription. We do not use third-party analytics.'],cookies:['Small settings, your choice.','Essential browser storage keeps your bag and remembers your cookie preferences. Optional analytics are currently turned off.','You can update your cookie choice at any time using Cookie settings in the footer. Your preference is stored in this browser.'],terms:['Clear terms matter.','Prices are shown in EUR. Orders submitted through this site are requests and remain unpaid until payment is arranged with the studio.','We ship worldwide, with free shipping on orders over $50. Product availability, delivery options, and any applicable charges are confirmed with your order. For questions about these terms, contact GR Studio.'],legal:['The details behind the studio.','GR Studio is the name of the store and creative studio behind this collection.','For business and tax registration details before placing an order, please contact GR Studio. Product and order questions are always welcome.'],account:['Your corner of the studio.','Customer accounts are not available yet. You can browse the collection and submit an order request as a guest.','Account sign-in, saved addresses, and order history will be available here when the studio introduces customer accounts.'],tracking:['Following a little journey.','Tracking details are not currently available on this site.','For an update about an order, contact the studio with your order reference. Delivery options and timing depend on the destination.'],payment:['A note about payment.','Online card payments are not available yet. Orders submitted on this site are saved as unpaid requests, and no card details are collected.','For the available payment options, contact GR Studio before placing an order.'],accessibility:['Designed to be easier to use.','We want everyone to be able to explore the collection and use this site comfortably.','If you have difficulty using any part of the site, let GR Studio know what happened so we can help and make improvements.']};
function infoPage(key){const [title,lead,body]=pages[key]||pages.about;const artKey=Object.hasOwn(pages,key)?key:'about';const pageArt={about:'online-shopping_po8w',contact:'files-sent_o4sc',faq:'add-document_oqbr',shipping:'online-shopping_po8w',returns:'order-status_swsl',privacy:'secure-server_lz9x',cookies:'secure-server_lz9x',terms:'terms_7l7t',legal:'terms_7l7t',account:'online-profile_v9c1',tracking:'order-status_swsl',payment:'online-shopping_po8w',accessibility:'online-profile_v9c1'};return `<section class="info-hero"><div class="info-hero-layout"><div class="info-copy"><span class="eyebrow">GR STUDIO / ${artKey.toUpperCase()}</span><h1>${title.split(' ').slice(0,-1).join(' ')} <em>${title.split(' ').slice(-1)}</em></h1><p class="info-lead">${esc(lead)}</p></div><div class="info-page-art"><img src="/source/page-illustrations/${pageArt[artKey]||'online-shopping_po8w'}.svg" alt="" decoding="async"></div></div></section><section class="info-body"><span class="eyebrow">A NOTE FROM THE STUDIO</span><p>${esc(body).replaceAll('\n','<br>')}</p><div class="info-disclaimer">For questions about a product, order, or delivery, get in touch with GR Studio.</div></section>`}
function socialSignInOptions(){return `<div class="social-login"><div class="social-login-divider"><span>OR</span></div><div class="social-login-buttons"><button class="social-login-button" type="button" disabled aria-label="Apple sign-in not connected"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M16.37 1.43c0 1.14-.42 2.2-1.25 3.18-1 1.18-2.2 1.86-3.51 1.75-.02-.14-.03-.28-.03-.42 0-1.09.48-2.26 1.32-3.16.42-.45.95-.83 1.49-1.13.53-.3 1.06-.47 1.59-.5.02.1.02.19.02.28ZM20.5 16.99c-.46 1.03-.68 1.5-1.28 2.41-.83 1.28-2 2.87-3.45 2.88-1.29.01-1.62-.84-3.37-.83-1.75.01-2.11.84-3.4.83-1.45-.01-2.56-1.45-3.39-2.73-2.32-3.56-2.56-7.75-1.13-9.97 1.02-1.58 2.63-2.51 4.15-2.51 1.54 0 2.52.84 3.79.84 1.24 0 1.99-.84 3.77-.84 1.35 0 2.78.73 3.8 2-3.34 1.83-2.8 6.62.51 7.91Z"/></svg><span>Apple</span></button><button class="social-login-button" type="button" disabled aria-label="Google sign-in not connected"><svg viewBox="0 0 48 48" aria-hidden="true"><path fill="#4285F4" d="M43.6 24.5c0-1.4-.1-2.7-.4-4H24v7.6h11a9.4 9.4 0 0 1-4.1 6.2v5h6.6c3.9-3.6 6.1-8.9 6.1-14.8Z"/><path fill="#34A853" d="M24 44c5.5 0 10.1-1.8 13.5-4.8l-6.6-5c-1.8 1.2-4.1 2-6.9 2-5.3 0-9.8-3.6-11.4-8.4H5.8v5.2A20 20 0 0 0 24 44Z"/><path fill="#FBBC05" d="M12.6 27.8a12 12 0 0 1 0-7.6V15H5.8a20 20 0 0 0 0 18Z"/><path fill="#EA4335" d="M24 11.8c3 0 5.7 1 7.8 3.1l5.8-5.8C34.1 5.8 29.5 4 24 4A20 20 0 0 0 5.8 15l6.8 5.2c1.6-4.8 6.1-8.4 11.4-8.4Z"/></svg><span>Google</span></button></div><p>Social sign-in is not connected yet.</p></div>`}
function accountPanel(data,section){const account=data.account,orders=data.orders||[],addresses=data.addresses||[];if(section==='overview'){const latest=orders[0];return `<div class="account-panel-heading"><span class="eyebrow">YOUR ACCOUNT</span><h2>Your studio, at a glance.</h2><p>Manage your details, addresses, and orders from here.</p></div><div class="account-stat-grid"><button data-account-section="orders"><span>${orders.length}</span><small>${orders.length===1?'Order':'Orders'}</small></button><button data-account-section="addresses"><span>${addresses.length}</span><small>${addresses.length===1?'Saved address':'Saved addresses'}</small></button></div><div class="account-panel-card"><div class="account-panel-card-head"><div><span class="eyebrow">RECENT ORDER</span><h3>${latest?esc(latest.id):'No orders yet'}</h3></div>${latest?`<span class="account-state">${esc(latest.fulfillment)}</span>`:''}</div>${latest?`<p>${new Date(latest.createdAt).toLocaleDateString()} ? ${latest.items.map(i=>`${esc(i.name)} ? ${i.quantity}`).join(', ')}</p><strong>${money(latest.total)}</strong><button class="account-inline-link" data-account-section="orders">View order history ${linkIcon()}</button>`:`<p>Your orders will appear here after checkout while you are signed in.</p><a class="account-inline-link" href="/collections">Explore the collection ${linkIcon()}</a>`}</div><div class="account-panel-card"><div class="account-panel-card-head"><div><span class="eyebrow">DEFAULT ADDRESS</span><h3>${addresses.find(x=>x.isDefault)?esc(addresses.find(x=>x.isDefault).label):'Add your first address'}</h3></div><button class="account-inline-link" data-account-section="addresses">Manage addresses ${linkIcon()}</button></div>${addresses.find(x=>x.isDefault)?addressMarkup(addresses.find(x=>x.isDefault)): '<p>Save a delivery address to make checkout quicker.</p>'}</div>`}if(section==='orders')return `<div class="account-panel-heading"><span class="eyebrow">ORDER HISTORY</span><h2>Your orders.</h2><p>Orders placed while signed in are listed here.</p></div>${orders.length?orders.map(o=>`<details class="account-order"><summary><span><strong>${esc(o.id)}</strong><small>${new Date(o.createdAt).toLocaleDateString()}</small></span><span class="account-order-status">${esc(o.fulfillment)} ? ${esc(o.paymentStatus)}</span><strong>${money(o.total)}</strong></summary><div class="account-order-detail"><div>${o.items.map(i=>`<p><span>${esc(i.name)} ? ${i.quantity}</span><strong>${money(i.lineTotal)}</strong></p>`).join('')}</div><div class="account-order-address"><span class="eyebrow">DELIVERING TO</span><p>${esc(o.customer.name)}<br>${esc(o.address.line1)}${o.address.line2?`<br>${esc(o.address.line2)}`:''}<br>${esc(o.address.city)}${o.address.region?`, ${esc(o.address.region)}`:''} ${esc(o.address.postalCode)}<br>${esc(o.address.country)}</p>${o.tracking?`<small>Tracking: ${esc(o.tracking)}</small>`:''}</div></div></details>`).join(''):`<div class="account-panel-card account-empty"><h3>No orders yet.</h3><p>Your order history will appear here when you place an order while signed in.</p><a class="button button-dark" href="/collections">Explore the collection ${linkIcon()}</a></div>`}`;if(section==='addresses')return `<div class="account-panel-heading"><span class="eyebrow">ADDRESS BOOK</span><h2>Saved addresses.</h2><p>Add and manage delivery addresses for a quicker checkout.</p></div><div class="address-grid">${addresses.map(a=>`<article class="saved-address ${a.isDefault?'is-default':''}"><div class="saved-address-head"><div><span class="eyebrow">${esc(a.label)}${a.isDefault?' ? DEFAULT':''}</span><strong>${esc(a.fullName)}</strong></div><button class="address-menu-button" type="button" data-address-edit="${esc(a.id)}">Edit</button></div><p>${esc(a.line1)}${a.line2?`<br>${esc(a.line2)}`:''}<br>${esc(a.city)}${a.region?`, ${esc(a.region)}`:''} ${esc(a.postalCode)}<br>${esc(a.country)}</p><div class="saved-address-actions">${a.isDefault?'':`<button type="button" data-address-default="${esc(a.id)}">Make default</button>`}<button class="address-delete" type="button" data-address-delete="${esc(a.id)}">Remove</button></div></article>`).join('')}</div><form class="account-form address-form" id="address-form"><div class="account-form-heading"><h3 id="address-form-title">Add an address</h3><button type="button" id="address-cancel-edit" hidden>Cancel edit</button></div><input type="hidden" name="id"><div class="address-fields"><label>Address label<input name="label" placeholder="Home, studio, etc." maxlength="40" required></label><label>Full name<input name="fullName" autocomplete="name" maxlength="100" required></label><label class="wide-field">Street address<input name="line1" autocomplete="address-line1" maxlength="150" required></label><label class="wide-field">Apartment, suite, etc. <small>Optional</small><input name="line2" autocomplete="address-line2" maxlength="150"></label><label>City<input name="city" autocomplete="address-level2" maxlength="80" required></label><label>Region or state<input name="region" autocomplete="address-level1" maxlength="80"></label><label>Postal code<input name="postalCode" autocomplete="postal-code" maxlength="30" required></label><label>Country<input name="country" autocomplete="country-name" maxlength="80" required></label></div><label class="address-default-check"><input type="checkbox" name="isDefault" ${addresses.length?'':'checked'}> Set as default delivery address</label><p class="form-error" id="address-error" aria-live="polite"></p><button class="button button-dark" id="address-submit">Save address ${linkIcon()}</button></form>`;if(section==='profile')return `<div class="account-panel-heading"><span class="eyebrow">PROFILE DETAILS</span><h2>Your details.</h2><p>Keep the name on your account up to date.</p></div><form class="account-form account-profile-form" id="profile-form"><label>Full name<input name="name" value="${esc(account.name)}" autocomplete="name" maxlength="100" required></label><label>Email address<input value="${esc(account.email)}" type="email" readonly><small>Email changes are not available yet.</small></label><p class="form-error" id="profile-message" aria-live="polite"></p><button class="button button-dark">Save details ${linkIcon()}</button></form>`;return `<div class="account-panel-heading"><span class="eyebrow">SIGN-IN & SECURITY</span><h2>Keep your account secure.</h2><p>Change your password using your current password.</p></div><form class="account-form account-profile-form" id="password-form"><label>Current password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label>New password<input name="newPassword" type="password" autocomplete="new-password" minlength="10" maxlength="128" required><small>Use at least 10 characters.</small></label><label>Confirm new password<input name="confirmPassword" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><p class="form-error" id="password-message" aria-live="polite"></p><button class="button button-dark">Update password ${linkIcon()}</button></form>`}
function addressMarkup(a){return `<p class="account-address-copy">${esc(a.fullName)}<br>${esc(a.line1)}${a.line2?`<br>${esc(a.line2)}`:''}<br>${esc(a.city)}${a.region?`, ${esc(a.region)}`:''} ${esc(a.postalCode)}<br>${esc(a.country)}</p>`}
async function accountPage(){try{const data=await api('/api/account/me');if(!data.authenticated)return `<section class="account-wrap"><div class="account-heading"><span class="eyebrow">GR STUDIO / YOUR ACCOUNT</span><h1>A little place<br>to <em>come back to.</em></h1><p>Track orders, save delivery addresses, and manage your details.</p></div><div class="account-card"><div class="account-tabs"><button class="active" type="button" data-account-tab="signup">Create account</button><button type="button" data-account-tab="login">Sign in</button></div><form class="account-form" id="account-signup"><label>Your name<input name="name" autocomplete="name" maxlength="100" required></label><label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label>Password<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="128" required></label><small>Use at least 10 characters.</small><p class="form-error" id="account-signup-error" aria-live="polite"></p><button class="button button-dark">Create your account ${linkIcon()}</button>${socialSignInOptions()}</form><form class="account-form" id="account-login" hidden><label>Email address<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><p class="form-error" id="account-login-error" aria-live="polite"></p><button class="button button-dark">Sign in ${linkIcon()}</button>${socialSignInOptions()}</form><p class="account-note">Your password is protected and never shown in your account.</p></div></section>`;accountState=data;accountSection='overview';updateAccountHeader(true);return `<section class="account-wrap"><div class="account-dashboard-head"><div><span class="eyebrow">GR STUDIO / YOUR ACCOUNT</span><h1>Welcome back,<br><em id="account-dashboard-name">${esc(data.account.name)}.</em></h1></div><button class="button button-outline" id="account-logout">Sign out</button></div><div class="account-layout"><nav class="account-nav" aria-label="Account sections">${[['overview','Overview'],['orders','Orders'],['addresses','Addresses'],['profile','Profile details'],['security','Password & security']].map(([id,label])=>`<button type="button" data-account-section="${id}" class="${id===accountSection?'active':''}">${label}${id==='orders'?`<span>${(data.orders||[]).length}</span>`:''}</button>`).join('')}</nav><div class="account-panel" id="account-panel">${accountPanel(data,accountSection)}</div></div></section>`}catch(e){return `<section class="account-wrap"><div class="empty-state"><h1>Your account is taking a pause.</h1><p>${esc(e.message)}</p></div></section>`}}
function showAccountSection(section){accountSection=section;document.querySelectorAll('.account-nav [data-account-section]').forEach(button=>button.classList.toggle('active',button.dataset.accountSection===section));const panel=$('#account-panel');if(panel){panel.innerHTML=accountPanel(accountState,section);bindAccountPanel()}}
async function refreshAccount(){const data=await api('/api/account/me');if(!data.authenticated){render();return}accountState=data;showAccountSection(accountSection)}
function bindAccountPanel(){document.querySelectorAll('#account-panel a[href^="/"]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();navigate(a.getAttribute('href'))}));document.querySelectorAll('#account-panel [data-account-section]').forEach(b=>b.addEventListener('click',()=>showAccountSection(b.dataset.accountSection)));$('#profile-form')?.addEventListener('submit',async e=>{e.preventDefault();const message=$('#profile-message');try{await api('/api/account/profile',{method:'PATCH',body:JSON.stringify({name:new FormData(e.target).get('name')})});message.textContent='Your details have been saved.';const data=await api('/api/account/me');accountState=data;$('#account-dashboard-name')?.replaceChildren(document.createTextNode(data.account.name))}catch(x){message.textContent=x.message}});$('#address-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target),id=form.get('id'),address={label:form.get('label'),fullName:form.get('fullName'),line1:form.get('line1'),line2:form.get('line2'),city:form.get('city'),region:form.get('region'),postalCode:form.get('postalCode'),country:form.get('country'),isDefault:form.get('isDefault')==='on'};try{await api(id?`/api/account/addresses/${encodeURIComponent(id)}`:'/api/account/addresses',{method:id?'PATCH':'POST',body:JSON.stringify(address)});await refreshAccount();showToast('Address saved.')}catch(x){$('#address-error').textContent=x.message}});document.querySelectorAll('[data-address-edit]').forEach(button=>button.addEventListener('click',()=>{const address=accountState.addresses.find(a=>a.id===button.dataset.addressEdit),form=$('#address-form');if(!address||!form)return;for(const key of ['label','fullName','line1','line2','city','region','postalCode','country'])form.elements[key].value=address[key]||'';form.elements.id.value=address.id;form.elements.isDefault.checked=address.isDefault;$('#address-form-title').textContent='Edit address';$('#address-submit').innerHTML=`Save changes ${linkIcon()}`;$('#address-cancel-edit').hidden=false;form.scrollIntoView({behavior:'smooth',block:'center'})}));$('#address-cancel-edit')?.addEventListener('click',()=>{const form=$('#address-form');form.reset();form.elements.id.value='';$('#address-form-title').textContent='Add an address';$('#address-submit').innerHTML=`Save address ${linkIcon()}`;$('#address-cancel-edit').hidden=true});document.querySelectorAll('[data-address-default]').forEach(button=>button.addEventListener('click',async()=>{try{await api(`/api/account/addresses/${encodeURIComponent(button.dataset.addressDefault)}/default`,{method:'PATCH'});await refreshAccount()}catch(x){showToast(x.message)}}));document.querySelectorAll('[data-address-delete]').forEach(button=>button.addEventListener('click',async()=>{if(!confirm('Remove this saved address?'))return;try{await api(`/api/account/addresses/${encodeURIComponent(button.dataset.addressDelete)}`,{method:'DELETE'});await refreshAccount()}catch(x){showToast(x.message)}}));$('#password-form')?.addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.target),message=$('#password-message');if(form.get('newPassword')!==form.get('confirmPassword')){message.textContent='The new passwords do not match.';return}try{await api('/api/account/password',{method:'POST',body:JSON.stringify({currentPassword:form.get('currentPassword'),newPassword:form.get('newPassword')})});e.target.reset();message.textContent='Your password has been updated.'}catch(x){message.textContent=x.message}})}
function bindAccount(){document.querySelectorAll('#app a[href^="/"]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();navigate(a.getAttribute('href'))}));document.querySelectorAll('[data-account-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-account-tab]').forEach(x=>x.classList.toggle('active',x===button));$('#account-signup').hidden=button.dataset.accountTab!=='signup';$('#account-login').hidden=button.dataset.accountTab!=='login'}));document.querySelectorAll('.account-nav [data-account-section]').forEach(button=>button.addEventListener('click',()=>showAccountSection(button.dataset.accountSection)));$('#account-signup')?.addEventListener('submit',async e=>{e.preventDefault();const error=$('#account-signup-error'),form=new FormData(e.target);try{const result=await api('/api/account/signup',{method:'POST',body:JSON.stringify({name:form.get('name'),email:form.get('email'),password:form.get('password')})});accountState={authenticated:true,account:result.account,orders:[],addresses:[]};updateAccountHeader(true);render()}catch(x){error.textContent=x.message}});$('#account-login')?.addEventListener('submit',async e=>{e.preventDefault();const error=$('#account-login-error'),form=new FormData(e.target);try{const result=await api('/api/account/login',{method:'POST',body:JSON.stringify({email:form.get('email'),password:form.get('password')})});accountState={authenticated:true,account:result.account,orders:[],addresses:[]};updateAccountHeader(true);render()}catch(x){error.textContent=x.message}});$('#account-logout')?.addEventListener('click',async()=>{try{await api('/api/account/logout',{method:'POST'});accountState=null;updateAccountHeader(false);render()}catch(e){showToast(e.message)}});bindAccountPanel()}
async function adminPage(){let status;try{status=await api('/api/admin/status')}catch{return `<section class="empty-state"><h1>Admin unavailable</h1><p>Start the local server to open the dashboard.</p></section>`}if(!status.configured)return `<section class="admin-wrap"><div class="admin-login"><span class="eyebrow">GR STUDIO / ADMINISTRATION</span><h1>Admin setup<br><em>needed.</em></h1><p>Set the server environment variable <code>GR_ADMIN_PASSWORD</code> and restart the server to enable administrator sign-in.</p></div></section>`;if(!status.authenticated)return `<section class="admin-wrap"><form class="admin-login" id="admin-login"><span class="eyebrow">GR STUDIO / PRIVATE AREA</span><h1>Good to<br><em>see you.</em></h1><label>Administrator password<input type="password" name="password" autocomplete="current-password" required></label><p class="form-error" id="admin-error"></p><button class="button button-dark">Sign in ${linkIcon()}</button><small>Server-side session required. Login attempts are rate-limited.</small></form></section>`;try{adminCatalog=await api('/api/admin/products');const os=await api('/api/admin/orders');const signups=await api('/api/admin/signups');return `<section class="admin-wrap"><div class="admin-heading"><div><span class="eyebrow">GR STUDIO / PRIVATE AREA</span><h1>Studio <em>desk.</em></h1></div><button class="button button-outline" id="admin-logout">Sign out</button></div><div class="admin-warning">Review product information, imagery, business details, shipping, tax, and policies before publishing.</div><div class="admin-tabs"><button class="active" data-tab="products">Products <span>${adminCatalog.length}</span></button><button data-tab="orders">Orders <span>${os.length}</span></button><button data-tab="signups">Sign-ups <span>${signups.filter(x=>x.status==='subscribed').length}</span></button></div><div id="admin-content">${adminProducts()}</div></section>`}catch(e){return `<section class="empty-state"><h1>Couldn’t load the studio desk.</h1><p>${esc(e.message)}</p></section>`}}
function adminProducts(){return `<div class="admin-table-head"><div><span class="eyebrow">PRODUCT CATALOG</span><h2>Every little thing.</h2></div><button class="button button-dark" id="new-product">+ New product</button></div><div class="admin-table">${adminCatalog.map(p=>`<div class="admin-product" data-admin-product="${esc(p.id)}"><div class="admin-thumb">${art(p)}</div><div><strong>${esc(p.name)}</strong><span>${esc(p.sku)} · ${esc(p.category)}</span></div><label>Price<input data-field="price" type="number" min="0" value="${p.price}"></label><label>Sale price<input data-field="salePrice" type="number" min="0" max="${Math.max(0,p.price-1)}" value="${p.salePrice||''}" placeholder="Enter price"></label><label>Stock<input data-field="stock" type="number" min="0" value="${p.stock}"></label><label>Status<select data-field="status"><option ${p.status==='published'?'selected':''}>published</option><option ${p.status==='draft'?'selected':''}>draft</option><option ${p.status==='archived'?'selected':''}>archived</option></select></label><button class="save-product" data-save="${esc(p.id)}">Save</button></div>`).join('')}</div><p class="admin-footnote">Catalog and orders are stored in the local SQLite database. Customer-facing and admin routes require the local server.</p>`}
function adminSignups(signups){return `<div class="admin-table-head"><div><span class="eyebrow">STUDIO LETTER</span><h2>People who opted in.</h2></div></div>${signups.length?`<div class="admin-table">${signups.map(x=>`<div class="signup-admin"><div><strong>${esc(x.email)}</strong><span>Joined ${new Date(x.createdAt).toLocaleString()} | consent recorded ${new Date(x.consentAt).toLocaleString()}</span></div><label>Status<select data-signup-status="${esc(x.id)}"><option value="subscribed" ${x.status==='subscribed'?'selected':''}>subscribed</option><option value="unsubscribed" ${x.status==='unsubscribed'?'selected':''}>unsubscribed</option></select></label></div>`).join('')}</div>`:`<div class="admin-empty">No newsletter sign-ups yet.</div>`}<p class="admin-footnote">Sign-ups are stored locally in the SQLite database. Status changes are saved immediately.</p>`}
function adminOrders(os){return `<div class="admin-table-head"><div><span class="eyebrow">ORDER DESK</span><h2>Every order, clearly.</h2></div></div>${os.length?`<div class="admin-table">${os.map(o=>`<div class="order-admin"><div><strong>${esc(o.id)}</strong><span>${new Date(o.createdAt).toLocaleString()} · ${esc(o.customer.name)}</span><span>${esc(o.customer.email)}</span></div><div class="order-products">${o.items.map(i=>`${esc(i.name)} × ${i.quantity}`).join('<br>')}</div><strong>${money(o.total)}</strong><span class="unpaid">${esc(o.paymentStatus)} · never auto-paid</span><label>Fulfillment<select data-order-status="${esc(o.id)}"><option ${o.fulfillment==='pending'?'selected':''}>pending</option><option ${o.fulfillment==='processing'?'selected':''}>processing</option><option ${o.fulfillment==='fulfilled'?'selected':''}>fulfilled</option><option ${o.fulfillment==='cancelled'?'selected':''}>cancelled</option></select></label></div>`).join('')}</div>`:`<div class="admin-empty">No orders have been recorded yet.</div>`}`}
function render(){if(location.pathname.replace(/\/$/,'')==='/shop')history.replaceState(null,'','/collections');const path=decodeURIComponent(location.pathname).replace(/\/$/,'')||'/';let content;if(path==='/')content=home();else if(path==='/collections')content=shop();else if(path==='/sale')content=salePage();else if(path.startsWith('/products/'))content=detail(path.slice(10));else if(path.startsWith('/collections/')){const cat=path.split('/').at(-1);const items=catalog.filter(p=>p.category.toLowerCase()===cat);content=`<section class="page-intro"><span class="eyebrow">A COLLECTION / ${esc(cat.toUpperCase())}</span><h1>${esc(cat)} <em>forms.</em></h1></section>`+`<section class="section">${grid(items.length?items:catalog)}</section>`}else if(path==='/cart')content=cartPage();else if(path==='/checkout')content=checkout();else if(path==='/admin')content='<div class="loading">Opening the studio desk?</div>';else if(path==='/account')content='<div class="loading">Opening your account...</div>';else content=infoPage(path.slice(1));$('#app').innerHTML=content;updateAccountHeader();document.querySelectorAll('.payment-list').forEach(el=>el.innerHTML=paymentMarks());$('#year').textContent=new Date().getFullYear();updateBag();bindPage();if(path==='/admin')adminPage().then(html=>{if(location.pathname==='/admin'){$('#app').innerHTML=html;bindAdmin()}});if(path==='/account')accountPage().then(html=>{if(location.pathname.replace(/\/$/,'')==='/account'){$('#app').innerHTML=html;bindAccount()}});if(path==='/checkout')hydrateCheckoutAccount();}
function bindPage(){document.querySelectorAll('a[href^="/"]').forEach(a=>a.addEventListener('click',e=>{if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();navigate(a.getAttribute('href'))}));document.querySelectorAll('[data-gallery-src]').forEach(b=>b.addEventListener('click',()=>{const main=$('#gallery-main-image');main.src=b.dataset.gallerySrc;document.querySelectorAll('.gallery-thumb').forEach(x=>x.classList.toggle('selected',x===b))}));document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.add;const q=Math.max(1,Number($('#quantity')?.value||1));const lines=bag(),line=lines.find(x=>x.id===id);if(line)line.quantity+=q;else lines.push({id,quantity:q});saveBag(lines);openBagDrawer(`Added ${catalog.find(x=>x.id===id)?.name||'item'} to your bag.`)}));document.querySelectorAll('[data-remove]').forEach(b=>b.addEventListener('click',()=>{saveBag(bag().filter(x=>x.id!==b.dataset.remove));render()}));document.querySelectorAll('[data-qty]').forEach(input=>input.addEventListener('change',()=>{let lines=bag();let line=lines.find(x=>x.id===input.dataset.qty);if(line)line.quantity=Math.max(1,Math.min(20,Number(input.value)||1));saveBag(lines);render()}));if($('#filter-pills')){$('#filter-pills').addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;document.querySelectorAll('.filter-pill').forEach(x=>x.classList.remove('active'));b.classList.add('active');applyFilters()});$('#sort').addEventListener('change',applyFilters)}document.querySelector('#newsletter-form')?.addEventListener('submit',e=>submitNewsletter(e,'#newsletter-message'));document.querySelector('#newsletter-form-home')?.addEventListener('submit',e=>submitNewsletter(e,'#home-newsletter-message'));$('#checkout-form')?.addEventListener('submit',checkoutSubmit);setupFlashCards()}
function applyFilters(){const cat=$('.filter-pill.active')?.dataset.category||'All';const term=$('#search-input').value.trim().toLowerCase();let items=catalog.filter(p=>(cat==='All'||p.category===cat)&&(!term||`${p.name} ${p.category}`.toLowerCase().includes(term)));const sort=$('#sort').value;if(sort==='low')items.sort((a,b)=>a.price-b.price);if(sort==='high')items.sort((a,b)=>b.price-a.price);if(sort==='az')items.sort((a,b)=>a.name.localeCompare(b.name));$('#result-count').textContent=`${items.length} ${items.length===1?'piece':'pieces'}`;$('#shop-grid').innerHTML=items.length?grid(items):'<div class="empty-filter">No pieces found. Try another search.</div>'}
async function hydrateCheckoutAccount(){try{const data=await api('/api/account/me');if(!data.authenticated||location.pathname!=='/checkout')return;const email=document.querySelector('#checkout-form [name="email"]'),name=document.querySelector('#checkout-form [name="name"]');if(email){email.value=data.account.email;email.readOnly=true}if(name)name.value=data.account.name;const card=document.querySelector('#checkout-form .checkout-card');if(card&&!card.querySelector('.account-checkout-note'))card.insertAdjacentHTML('beforeend','<p class="account-checkout-note">Signed in: this order will be saved in your account.</p>');const addresses=data.addresses||[],picker=$('#saved-address-picker');if(addresses.length&&picker){picker.hidden=false;picker.innerHTML=`<label>Use a saved address<select id="saved-address-select"><option value="">Enter a different address</option>${addresses.map(a=>`<option value="${esc(a.id)}" ${a.isDefault?'selected':''}>${esc(a.label)} ? ${esc(a.city)}, ${esc(a.country)}</option>`).join('')}</select></label>`;const select=$('#saved-address-select'),applyAddress=id=>{const a=addresses.find(x=>x.id===id);if(!a)return;for(const key of ['line1','line2','city','region','postalCode','country']){const field=$(`#checkout-form [name="${key}"]`);if(field){if(key==='country'&&field.tagName==='SELECT'&&!Array.from(field.options).some(option=>option.value===a[key]))field.add(new Option(a[key],a[key]));field.value=a[key]||''}}};select.addEventListener('change',()=>{if(select.value)applyAddress(select.value);else for(const key of ['line1','line2','city','region','postalCode','country']){$(`#checkout-form [name="${key}"]`).value=''}});const preferred=addresses.find(a=>a.isDefault);if(preferred)applyAddress(preferred.id)}}catch{}}
async function submitNewsletter(e,messageSelector){e.preventDefault();const form=e.target,message=$(messageSelector),button=form.querySelector('button');button.disabled=true;message.textContent='Saving your signup...';try{const data=new FormData(form);const result=await api('/api/newsletter',{method:'POST',body:JSON.stringify({email:data.get('email'),consent:data.get('consent')==='on'})});message.textContent=result.message;form.reset()}catch(err){message.textContent=err.message}finally{button.disabled=false}}
async function checkoutSubmit(e){e.preventDefault();const form=new FormData(e.target),lines=bag();const address={};for(const k of ['line1','line2','city','region','postalCode','country'])address[k]=form.get(k)||'';try{const order=await api('/api/orders',{method:'POST',body:JSON.stringify({customer:{name:form.get('name'),email:form.get('email')},address,items:lines})});saveBag([]);$('#app').innerHTML=`<section class="order-confirm"><span class="eyebrow">A NOTE FROM THE STUDIO</span><div class="confirm-mark">gr<span>&deg;</span></div><div class="order-confirm-art"><img src="/source/page-illustrations/order-confirmed_m9e9.svg" alt="" decoding="async"></div><h1>Your request is<br><em>on the books.</em></h1><p>Reference <strong>${esc(order.id)}</strong></p><div class="payment-disabled"><strong>Payment is arranged separately.</strong><span>Your order request has been saved without payment. No card details were collected.</span></div><a class="button button-dark" href="/collections" id="return-shop">Back to the collection ${linkIcon()}</a></section>`;bindPage();window.scrollTo(0,0)}catch(err){showToast(err.message)}}
function bindAdmin(){$('#admin-login')?.addEventListener('submit',async e=>{e.preventDefault();const err=$('#admin-error');try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({password:new FormData(e.target).get('password')})});render()}catch(x){err.textContent=x.message}});$('#admin-logout')?.addEventListener('click',async()=>{await api('/api/admin/logout',{method:'POST'});render()});document.querySelectorAll('[data-tab]').forEach(t=>t.addEventListener('click',async()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));t.classList.add('active');$('#admin-content').innerHTML='<div class="loading">One moment…</div>';if(t.dataset.tab==='products')$('#admin-content').innerHTML=adminProducts();else if(t.dataset.tab==='orders')$('#admin-content').innerHTML=adminOrders(await api('/api/admin/orders'));else $('#admin-content').innerHTML=adminSignups(await api('/api/admin/signups'));bindAdminContent()}));bindAdminContent()}
function bindAdminContent(){$('#new-product')?.addEventListener('click',()=>{const name=prompt('Product name');if(!name)return;const category=prompt('Category','Objects')||'Objects';const price=Number(prompt('Price in EUR','0'));const stock=Number(prompt('Stock quantity','0'));api('/api/admin/products',{method:'POST',body:JSON.stringify({name,category,price,stock,description:'Add a verified product description.'})}).then(()=>render()).catch(e=>showToast(e.message))});document.querySelectorAll('[data-save]').forEach(b=>b.addEventListener('click',async()=>{const row=b.closest('[data-admin-product]');try{await api(`/api/admin/products/${encodeURIComponent(b.dataset.save)}`,{method:'PATCH',body:JSON.stringify({price:row.querySelector('[data-field="price"]').value,salePrice:row.querySelector('[data-field="salePrice"]').value,stock:row.querySelector('[data-field="stock"]').value,status:row.querySelector('[data-field="status"]').value})});showToast('Product updated.');}catch(e){showToast(e.message)}}));document.querySelectorAll('[data-order-status]').forEach(sel=>sel.addEventListener('change',async()=>{try{await api(`/api/admin/orders/${encodeURIComponent(sel.dataset.orderStatus)}`,{method:'PATCH',body:JSON.stringify({fulfillment:sel.value})});showToast('Fulfillment status updated.')}catch(e){showToast(e.message)}}));document.querySelectorAll('[data-signup-status]').forEach(sel=>sel.addEventListener('change',async()=>{try{await api(`/api/admin/signups/${encodeURIComponent(sel.dataset.signupStatus)}`,{method:'PATCH',body:JSON.stringify({status:sel.value})});showToast('Signup status updated.')}catch(e){showToast(e.message)}}))}
function navigate(path){
 if(typeof path!=='string'||!path.startsWith('/')||path.startsWith('//'))return;
 closeBagDrawer(false);
 history.pushState({},'',path);
 render();
 window.scrollTo(0,0);
 $('#main-nav').classList.remove('open');
 $('#search-panel').classList.remove('open');
 $('#search-toggle').setAttribute('aria-expanded','false');
}
$('#bag-trigger').addEventListener('click',()=>openBagDrawer());$('#bag-drawer').addEventListener('click',e=>{if(e.target===e.currentTarget){closeBagDrawer();return}const close=e.target.closest('[data-bag-close]');if(close){closeBagDrawer();return}const go=e.target.closest('[data-bag-go]');if(go){navigate(go.dataset.bagGo);return}const action=e.target.closest('[data-bag-action]');if(!action)return;const lines=bag(),line=lines.find(x=>x.id===action.dataset.id),product=catalog.find(x=>x.id===action.dataset.id);if(!line)return;if(action.dataset.bagAction==='remove'){saveBag(lines.filter(x=>x.id!==line.id));bagStatusMessage=`Removed ${product?.name||'item'} from your bag.`}else{line.quantity=Math.max(1,line.quantity+(action.dataset.bagAction==='increase'?1:-1));saveBag(lines);bagStatusMessage=`${product?.name||'Item'} quantity: ${line.quantity}.`}renderBagDrawer()});$('#bag-drawer').addEventListener('cancel',e=>{e.preventDefault();closeBagDrawer()});$('#bag-drawer').addEventListener('close',()=>{clearTimeout(bagDrawerCloseTimer);const dialog=$('#bag-drawer'),trigger=$('#bag-trigger');dialog.classList.remove('is-closing');dialog.inert=false;trigger.setAttribute('aria-expanded','false');if(dialog.dataset.restoreFocus==='true')trigger.focus({preventScroll:true})});
window.addEventListener('popstate',render);
$('#menu-toggle').addEventListener('click',()=>$('#main-nav').classList.toggle('open'));
$('#search-toggle').addEventListener('click',()=>{const p=$('#search-panel'),open=!p.classList.contains('open');p.classList.toggle('open',open);$('#search-toggle').setAttribute('aria-expanded',String(open));if(open)$('#search-input').focus();else navigate('/collections')});$('#search-close').addEventListener('click',()=>$('#search-panel').classList.remove('open'));$('#search-input').addEventListener('input',()=>{if(location.pathname!='/collections')navigate('/collections');if($('#filter-pills'))applyFilters()});
const consent=localStorage.getItem('gr-cookie-choice');if(!consent)$('#cookie-banner').hidden=false;$('#cookie-accept').addEventListener('click',()=>cookieChoice('accepted'));$('#cookie-reject').addEventListener('click',()=>cookieChoice('essential-only'));$('#cookie-customize').addEventListener('click',()=>{cookieChoice('essential-only');showToast('Essential storage only. Optional tracking is off.')});$('#cookie-settings').addEventListener('click',()=>{$('#cookie-banner').hidden=false});function cookieChoice(v){localStorage.setItem('gr-cookie-choice',v);$('#cookie-banner').hidden=true}updateBag();syncAccountHeader();api('/api/products').then(ps=>{catalog=ps;render()}).catch(()=>{$('#app').innerHTML='<section class="empty-state"><h1>The studio is taking a pause.</h1><p>Start the local server with <code>node server.js</code> to open the storefront.</p></section>'});

